class Solution {
public:
    int findTheCity(int n, vector<vector<int>>& edges, int distanceThreshold) {
        vector<vector<pair<int, int>>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back({e[2], e[1]});
            adj[e[1]].push_back({e[2], e[0]});
        }
        auto getReachable = [&](int src) -> int {
            vector<int> dist(n, -1);
            priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
            pq.push({0, src});
            int count = 0;
            while (!pq.empty()) {
                auto [d, u] = pq.top(); pq.pop();
                if (dist[u] != -1) continue;
                dist[u] = d;
                if (u != src) ++count;
                for (auto& [w, v] : adj[u]) {
                    if (dist[v] == -1 && d + w <= distanceThreshold) {
                        pq.push({d + w, v});
                    }
                }
            }
            return count;
        };
        int minCount = 1e9, bestCity = -1;
        for (int i = 0; i < n; ++i) {
            int count = getReachable(i);
            if (count <= minCount) {
                minCount = count;
                bestCity = i;
            }
        }
        return bestCity;
    }
};

class Solution {
    public int findTheCity(int n, int[][] edges, int distanceThreshold) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[2], e[1]});
            adj.get(e[1]).add(new int[]{e[2], e[0]});
        }
        int minCount = Integer.MAX_VALUE, bestCity = -1;
        for (int i = 0; i < n; i++) {
            int count = getReachable(i, n, adj, distanceThreshold);
            if (count <= minCount) {
                minCount = count;
                bestCity = i;
            }
        }
        return bestCity;
    }
    private int getReachable(int src, int n, List<List<int[]>> adj, int threshold) {
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.add(new int[]{0, src});
        int count = 0;
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0], u = cur[1];
            if (dist[u] != -1) continue;
            dist[u] = d;
            if (u != src) count++;
            for (int[] edge : adj.get(u)) {
                int w = edge[0], v = edge[1];
                if (dist[v] == -1 && d + w <= threshold) {
                    pq.add(new int[]{d + w, v});
                }
            }
        }
        return count;
    }
}

var findTheCity = function(n, edges, distanceThreshold) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([w, v]);
        adj[v].push([w, u]);
    }
    function getReachable(src) {
        const dist = new Array(n).fill(-1);
        const pq = [[0, src]];
        let count = 0;
        while (pq.length > 0) {
            pq.sort((a, b) => a[0] - b[0]);
            const [d, u] = pq.shift();
            if (dist[u] !== -1) continue;
            dist[u] = d;
            if (u !== src) count++;
            for (const [w, v] of adj[u]) {
                if (dist[v] === -1 && d + w <= distanceThreshold) {
                    pq.push([d + w, v]);
                }
            }
        }
        return count;
    }
    let minCount = Infinity, bestCity = -1;
    for (let i = 0; i < n; i++) {
        const count = getReachable(i);
        if (count <= minCount) {
            minCount = count;
            bestCity = i;
        }
    }
    return bestCity;
};
